package com.treepeople.leapmindtts.service.profile.platform;
import java.math.BigDecimal; import java.time.Instant; import java.util.List;
public record ExplainingProfileContext(Long userId, String sceneType, ProfileContextStatus profileStatus, String statusReason, Long profileVersion, Instant computedAt, Instant lastUpdated, BigDecimal confidence, ProfileAvailability availability, String grade, ProfileKnowledgeContext knowledgeContext, List<ProfileRecentConfusion> recentConfusions, String preferredExplanationStyle, String learningPace, String summaryText) {
    public ExplainingProfileContext { boolean facts = grade != null || knowledgeContext != null || !ProfileContextFields.list(recentConfusions).isEmpty() || preferredExplanationStyle != null || learningPace != null || summaryText != null; ProfileContextFields.envelope(userId, sceneType, "explaining", profileStatus, statusReason, profileVersion, computedAt, lastUpdated, confidence, availability, facts); recentConfusions = ProfileContextFields.list(recentConfusions, 3, "recentConfusions"); preferredExplanationStyle = ProfileContextFields.explanationStyle(preferredExplanationStyle); learningPace = ProfileContextFields.pace(learningPace); summaryText = ProfileContextFields.summary(summaryText); }
}
